function initScrollProgress(){const t=document.createElement("div");t.id="scroll-progress",t.className="fixed top-0 left-0 h-1 bg-accent z-[60] transition-all duration-100 ease-out",t.style.width="0%",document.body.appendChild(t),window.addEventListener("scroll",()=>{const e=(document.documentElement.scrollTop||document.body.scrollTop)/(document.documentElement.scrollHeight-document.documentElement.clientHeight)*100;t.style.width=`${e}%`},{passive:!0})}function initBackToTop(){const t=document.createElement("button");t.id="back-to-top",t.innerHTML='\n    <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">\n      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 10l7-7m0 0l7 7m-7-7v18"></path>\n    </svg>\n  ',t.className="fixed bottom-8 right-8 p-3 bg-primary text-white rounded-full shadow-lg opacity-0 translate-y-10 transition-all duration-300 z-40 hover:bg-accent focus:outline-none pointer-events-none hidden md:flex items-center justify-center",t.setAttribute("aria-label",i18n.t("ui.scrollToTop")||"Scroll to top"),document.body.appendChild(t),window.addEventListener("scroll",()=>{window.scrollY>300?(t.classList.remove("opacity-0","translate-y-10","pointer-events-none"),t.classList.add("opacity-100","translate-y-0","pointer-events-auto")):(t.classList.add("opacity-0","translate-y-10","pointer-events-none"),t.classList.remove("opacity-100","translate-y-0","pointer-events-auto"))},{passive:!0}),t.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})})}document.addEventListener("DOMContentLoaded",()=>{initScrollProgress(),initBackToTop()});